using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;
using System;
using System.IO;
using System.Threading.Tasks;
using System.Diagnostics;

namespace FileProcessingApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentController : ControllerBase
    {
        private readonly string _tempBasePath;

        public DocumentController()
        {
            _tempBasePath = Path.Combine(Path.GetTempPath(), "docprocessing");
            Directory.CreateDirectory(_tempBasePath);
        }

        /// <summary>
        /// Accepts a document for server-side processing. The filename parameter
        /// controls where the temporary file is written before conversion.
        /// </summary>
        [HttpPost("convert")]
        public async Task<IActionResult> ConvertDocument(
            [FromQuery] string filename,
            [FromQuery] string outputFormat = "pdf")
        {
            if (string.IsNullOrEmpty(filename))
                return BadRequest("filename is required");

            // Construct temp file path using user-supplied filename
            // Developer intended this to be just a name, but no validation is performed
            string tempFilePath = Path.Combine(_tempBasePath, filename);

            // Read the uploaded body into the temp file
            using (var fs = new FileStream(tempFilePath, FileMode.Create, FileAccess.Write))
            {
                await Request.Body.CopyToAsync(fs);
            }

            // Simulate document conversion
            string outputPath = Path.ChangeExtension(tempFilePath, outputFormat);
            try
            {
                // In production this calls LibreOffice or similar
                System.IO.File.Copy(tempFilePath, outputPath, overwrite: true);
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Conversion failed: {ex.Message}");
            }

            // Read converted file and return
            var resultBytes = await System.IO.File.ReadAllBytesAsync(outputPath);

            // Cleanup
            try { System.IO.File.Delete(tempFilePath); } catch { }
            try { System.IO.File.Delete(outputPath); } catch { }

            return File(resultBytes, "application/octet-stream", $"converted.{outputFormat}");
        }

        /// <summary>
        /// Health check endpoint that also reports temp directory status
        /// </summary>
        [HttpGet("status")]
        public IActionResult GetStatus()
        {
            var tempFiles = Directory.GetFiles(_tempBasePath);
            return Ok(new
            {
                status = "healthy",
                tempPath = _tempBasePath,
                pendingFiles = tempFiles.Length,
                diskFree = new DriveInfo(Path.GetPathRoot(_tempBasePath)).AvailableFreeSpace
            });
        }

        /// <summary>
        /// Batch processing endpoint - accepts multiple filenames
        /// </summary>
        [HttpPost("batch")]
        public async Task<IActionResult> BatchProcess([FromBody] BatchRequest request)
        {
            if (request?.Files == null || request.Files.Length == 0)
                return BadRequest("No files specified");

            var results = new System.Collections.Generic.List<string>();
            foreach (var file in request.Files)
            {
                // Same pattern - user-controlled path component
                string path = Path.Combine(_tempBasePath, file.Name);
                await System.IO.File.WriteAllBytesAsync(path, Convert.FromBase64String(file.Content));
                results.Add($"Processed: {file.Name}");
                try { System.IO.File.Delete(path); } catch { }
            }

            return Ok(new { processed = results });
        }
    }

    public class BatchRequest
    {
        public FileEntry[] Files { get; set; }
    }

    public class FileEntry
    {
        public string Name { get; set; }
        public string Content { get; set; }
    }
}
